Section Stage.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis EXT : HAJ.asan_ext_ok L ar SCFG HI PMA.EXT.
Let LYa := PMA.ly_as0 L C LY.

Theorem grow1 : PMA.opnew_spec L ar HI -> forall (fx : FPState) R M model K LBX FF LK Aw cr v b k stk sp r p1 p2 m n,
    ri_inv HI (PQMA.mvec_own b k ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA PMA.AD L ar R M sp r 0 ->
    getr R (reg 10) = Z_to_bv 64 v -> PMSPA.aobjA FF v 24 -> v mod 8 = 0 -> PMSPA.accA M v 24 ->
    PQMA.mvec_at RSEGS PMSPA.accA PMSPA.annA M v b k stk -> Z.of_nat (length stk) = 2 ^ k -> k <= 10 ->
    getr R (reg 11) = Z_to_bv 64 p1 -> getr R (reg 12) = Z_to_bv 64 p2 -> p1 mod 4 = 0 -> p2 mod 8 = 0 ->
    byte_at M (S p1) 0 -> byte_at M (S p2) 0 ->
    PNAEK.argp (ar_sptop ar) FF sp v p1 4 -> PNAEK.argp (ar_sptop ar) FF sp v p2 8 ->
    L5.u32_at RSEGS M p1 m -> L5.u64_at RSEGS M p2 n -> 0 <= m < 2 ^ 31 -> 0 <= n < 2 ^ 64 -> acredit_ok L cr (24 * 2 ^ (k + 1)) ->
    PMSTA.base_okA RSEGS PMA.AD M ->
    (forall (fx6 : FPState) R6 M6 model6 Aw6 B, NEAEPGS.gmid L ar HI R M model LBX FF LK Aw cr v b k stk sp p1 p2 m n B R6 M6 model6 Aw6 ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx6 R6 0xc66a4 M6 model6) K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R 0xc5fb4 M model) K.
Proof.
